protected boolean isPOSOrder(SalesTable _salesTable)
{
    boolean ret = next isPOSOrder(_salesTable);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ret = ret && !_salesTable.isGUPSalesOrder();
    }

    return ret;
}

[SysClientCacheDataMethodAttribute(true)]
public display GUPCalculationSequenceNum displayPricingSequence()
{
    GUPPriceComponentCodeSetup priceComponentCodeSetup;
    MarkupAutoTable markupAutoTable;

    select firstonly CalculationSequence from priceComponentCodeSetup
        join markupAutoTable
            where priceComponentCodeSetup.PricingTree == 0
               && markupAutoTable.recId == this.MarkupAutoTableRecId
               && markupAutoTable.PriceComponentCodeName == priceComponentCodeSetup.PriceComponentCodeName;

    return priceComponentCodeSetup.CalculationSequence;
}
